// Radar YouTube del lunedì (Marco, 25/10/2026: «prepara il flusso n8n del radar»). Stessa regola di script/radar-youtube.mjs:
// visite / mediana del canale per formato (Short o lungo), solo video di 2–14 giorni, soglia 2×.
// Canali e ID dal repository pubblico (dati/radar-canali.json, dati/radar-id.json): niente chiavi, niente credenziali.
// «Forse già fatto»: un nome del titolo (con una cifra, o lungo almeno 6 lettere) compare nel nome di un nostro video o notizia.
const RAW = 'https://raw.githubusercontent.com/MarcoDeliaBot/freellmrank/main/';
const API = 'https://api.github.com/repos/MarcoDeliaBot/freellmrank/contents/';
const GIORNO = 86400000, ETA_MIN = 2, ETA_MAX = 14, SOGLIA = 2;
const get = (url) => this.helpers.httpRequest({ url, headers: { 'User-Agent': 'freellmarena-radar' }, json: false });
const json = async (url) => { const t = await get(url); return typeof t === 'string' ? JSON.parse(t) : t; };
const testo = (s) => s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const mediana = (a) => { const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const n = (x) => x.toLocaleString('it-IT');

const { canali } = await json(RAW + 'dati/radar-canali.json');
const ids = await json(RAW + 'dati/radar-id.json');
const nostri = [];
for (const cartella of ['contenuti/video', 'contenuti/notizie']) {
  try {
    for (const f of await json(API + cartella)) if (f.name.endsWith('.json')) { const nome = f.name.slice(0, -5).toLowerCase(); nostri.push({ nome, pezzi: new Set(nome.split('-')) }); }
  } catch (e) { /* senza elenco, niente «forse già fatto» */ }
}
// parole troppo comuni per dire che parliamo della stessa cosa
const COMUNI = new Set('google openai anthropic claude gemini chatgpt nvidia deepseek actually should tested insane crazy discovery researcher launch launches update agent agents coding model models release review this that with your just what from have fully back fast faster makes massive real look right after open best flies could wrong smart they shutting down built lightest fastest free local news here will than more into about over only even when then them were been being does here very most much like new and the for its how show teams gpt security research reasoning benchmark benchmarks engineer opensource sourced professionals'.split(' '));
// almeno due parole del titolo uguali a pezzi del nome del file (es. «flint» e «40b»), o una sola se lunga e rara (es. «deepinfer»)
const giaFatto = (titolo) => {
  const parole = [...new Set(titolo.toLowerCase().replace(/[^a-z0-9.\s-]/g, ' ').split(/[\s-]+/).map((p) => p.replace(/^\.+|\.+$/g, '')).filter((p) => p.length >= 3 && !COMUNI.has(p) && /[a-z]/.test(p)))];
  let meglio = null;
  for (const f of nostri) {
    const prese = parole.filter((p) => f.pezzi.has(p));
    if ((prese.length >= 2 || prese.some((p) => p.length >= 8)) && (!meglio || prese.length > meglio.prese.length)) meglio = { prese, file: f.nome };
  }
  return meglio && { parola: meglio.prese.join(', '), file: meglio.file };
};

const ora = Date.now(), trovati = [], saltati = [], letti = [];
for (const h of canali) {
  const id = ids[h];
  if (!id) { saltati.push(`@${h}: manca l'ID (eseguire una volta node script/radar-youtube.mjs)`); continue; }
  try {
    const x = await get(`https://www.youtube.com/feeds/videos.xml?channel_id=${id}`);
    const nome = testo(x.match(/<title>([^<]*)<\/title>/)?.[1] || h);
    letti.push(nome);
    const video = [...x.matchAll(/<entry>([\s\S]*?)<\/entry>/g)].map(([, e]) => ({
      id: e.match(/<yt:videoId>([^<]+)/)[1],
      titolo: testo(e.match(/<title>([^<]*)<\/title>/)?.[1] || ''),
      short: /youtube\.com\/shorts\//.test(e),
      eta: (ora - new Date(e.match(/<published>([^<]+)/)[1])) / GIORNO,
      visite: Number(e.match(/<media:statistics views="(\d+)"/)?.[1] || 0),
    }));
    for (const formato of [true, false]) {
      const maturi = video.filter((v) => v.short === formato && v.eta >= ETA_MIN);
      if (maturi.length < 3) continue;
      const med = mediana(maturi.map((v) => v.visite)) || 1;
      for (const v of maturi) if (v.eta <= ETA_MAX && v.visite / med >= SOGLIA) trovati.push({ ...v, canale: nome, mediana: Math.round(med), volte: v.visite / med });
    }
  } catch (e) { saltati.push(`@${h}: ${e.message}`); }
}
trovati.sort((a, b) => b.volte - a.volte);

const oggi = new Date(ora).toISOString().slice(0, 10);
const td = 'style="padding:6px 8px;border-bottom:1px solid #ddd;vertical-align:top"';
const righe = trovati.map((v) => {
  const f = giaFatto(v.titolo);
  const fatto = f ? `<br><span style="color:#0f7a5a">forse già fatto da noi: «${esc(f.parola)}» in ${esc(f.file)}</span>` : '';
  return `<tr><td ${td}><b style="color:#d4312a">${v.volte.toFixed(1).replace('.', ',')}×</b></td><td ${td}><a href="https://youtu.be/${v.id}">${esc(v.titolo)}</a><br><span style="color:#5b6676">${esc(v.canale)} · ${v.short ? 'Short' : 'Lungo'} · ${Math.floor(v.eta)} giorni</span>${fatto}</td><td ${td}>${n(v.visite)}<br><span style="color:#5b6676">solite ${n(v.mediana)}</span></td></tr>`;
}).join('');
const html = `<div style="font-family:system-ui,sans-serif;max-width:760px">
<p><b>Radar YouTube del ${oggi}.</b> Letti ${letti.length} canali su ${canali.length}. Trovati <b>${trovati.length} video</b> con almeno ${SOGLIA} volte le visite solite del loro canale (ultimi ${ETA_MAX} giorni).</p>
<p>Da guardare: i temi nostri (modelli aperti o gratis, hardware per modelli locali) ancora senza la riga verde «forse già fatto».</p>
<table style="border-collapse:collapse;font-size:14px"><tr><th align="left" ${td}>Volte</th><th align="left" ${td}>Video</th><th align="left" ${td}>Visite</th></tr>${righe}</table>
<p style="color:#5b6676;font-size:13px">«Volte» = visite del video diviso la mediana del canale per lo stesso formato. Numeri dal feed pubblico di YouTube. ${saltati.length ? 'Saltati: ' + esc(saltati.join('; ')) + '.' : 'Nessun canale saltato.'} Canali in dati/radar-canali.json.</p></div>`;
return [{ json: { oggetto: `FreeLLMArena · radar YouTube: ${trovati.length} video sopra il solito (${oggi})`, html, letti: letti.length, trovati: trovati.length, saltati } }];
